all, commissioning, inspection -> page ''/''", "LinkedIn URL -> db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Solar Installation Company in St. Louis, MO", "founded_year": "2006", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/straightup-solar/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='straightup-solar' AND approved AND profile IS NULL;
UPDATE companies SET description='Strategy Plastics operates a 40,000-square-foot facility in Williamston, South Carolina, roughly 25 miles from the Greenville-Spartanburg Airport. The company was acquired in June 2013 and has doubled in size since then, growing into a full-service injection molding operation.

