UPDATE companies SET description='Tabb Textile Company Inc. was founded in 1972 in Opelika, Alabama, as a family-owned and operated business. The company began as a converter, importer, and domestic manufacturer of fabrics and finished textile goods, and today it is led by CEO Zach Fenster.

The firm converts, imports, and manufactures a range of textiles including linens, woven and knit fabrics, apparel, and finished goods. It operates a 250,000-square-foot flagship fulfillment center in Opelika, supplemented by multiple distribution centers spanning the East and West coasts. Capabilities include custom specifications, Kaumagraphing for logos, Pantone color matching, private labeling, custom printing, and cut-and-sew services. Quality control involves on-site inspections and ASTM lab testing upon request.

Tabb Textile serves both B2B and B2G markets, with a focus on government agencies (including the Department of Defense, Defense Logistics Agency, Department of Health and Human Services, Department of Education, Department of Transportation, and Department of Veterans Affairs), healthcare facilities, hospitality businesses, commercial laundries, correctional institutions, and apparel manufacturers. The company holds a GSA Schedule contract and has multiple award agreements with federal, state, and local entities.

The company emphasizes supply-chain consistency through trained staff, modern manufacturing technology, long-term supplier relationships, and a comprehensive quality system. It differentiates itself with a large-stock inventory program, quick lead times from coast-to-coast warehouses, and a customer-service approach described as trustworthy and approachable.', certifications=ARRAY['GSA Schedule']::text[], profile='{"capabilities": ["Textile converting", "Importing", "Domestic manufacturing", "Custom textile product development", "Linens and bedding production", "Woven and knit fabric sourcing", "Garment and textile manufacturing", "Cut and sew operations", "Raw fiber processing", "Kaumagraphing (custom logo application)", "Pantone color matching", "Private labeling", "Custom printing on apparel", "On-site quality inspections", "ASTM lab testing", "Large stock inventory management", "Multi-location distribution", "Government contracting (GSA Schedule)"], "industries": ["Government (federal, state, local)", "Healthcare", "Hospitality", "Commercial laundries", "Apparel manufacturing", "Correctional facilities", "Defense (DOD/DLA)", "Health and Human Services (HHS)", "Education (DOE)", "Transportation (DOT)", "Veterans Affairs (VA)", "Fashion brands"], "materials": ["Linens", "Woven fabrics", "Knit fabrics", "Non-woven fabrics", "Apparel textiles", "Raw fibers"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Large stock inventory with coast-to-coast distribution centers", "On-site quality inspections and ASTM lab testing", "Custom specifications including custom logos, color matching, private labeling", "GSA Schedule holder for government contracts", "Family-owned and operated since 1972"], "facts_used": ["Founded 1972 -> db, homepage", "Headquarters Opelika, Alabama -> db, homepage", "Family-owned & operated -> homepage", "250,000 sq ft fulfillment center in Opelika -> homepage", "GSA Schedule holder -> db, homepage", "Industries served: Government, Healthcare, Hospitality, Laundries, Correctional, Apparel -> homepage", "Custom specifications, Kaumagraphing, Pantone matching, private labeling, custom printing -> homepage", "On-site inspections, ASTM lab testing -> homepage", "Coast-to-coast distribution centers -> homepage", "CEO Zach Fenster -> homepage", "Converter, importer, USA manufacturer -> db description, homepage"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We are one of the nation''s leading converters, importers, and \"Made in USA\" manufacturers of fabrics and finished textile goods.", "founded_year": "1972", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/tabb-textile-company-inc./"], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='tabb-textile-systems-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Taylor Packaging Corporation has operated from Imperial, Missouri since 1980. The company was founded as a family-owned business and continues as a female-owned and operated enterprise. Its Midwest location is intended to reduce shipping lead times and costs for customers across the region.

The company manufactures custom thermoformed plastic packaging, offering a full range of services from design and prototyping through tooling, production, assembly, and fulfillment. It runs a stock tooling program that includes more than 300 standard cavities and blisters and over 100 clamshell sizes, which can eliminate or reduce tooling expenses and accelerate time to market. Materials processed include clear, recycled, virgin, and color-matched plastics.

Taylor Packaging serves retail and shipping sectors, along with various other industries that require custom plastic packaging for product visibility and protection. Its VersaCLAM™ line provides ready-to-use clamshell and blister solutions, while custom development supports unique product presentations.

The company emphasizes sustainable practices, reporting a 95% recycling rate for production scrap and powering its facility with LED lighting and solar panels. Its female leadership has been recognized by the St. Louis Business Journal as a Top Women Business Owner for multiple years, and the operation was featured on the ION Television Network’s “World’s Greatest” series.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Thermoforming", "Prototyping", "Assembly", "JIT Delivery", "Drop Shipping", "Packaging Design", "Tooling", "Stock Tooling Program", "Fulfillment", "Distribution", "Custom Packaging Development"], "industries": ["Retail", "Shipping", "Various industries"], "materials": ["Clear plastic", "Recycled plastic", "Virgin plastic", "Color-matched plastic"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Patented VersaCLAM\u2122 technology", "Stock tooling program with 300+ standard cavities and 100+ clamshell sizes", "95% scrap recycling rate", "Facility powered by LED lighting and solar panels", "Female-owned and operated since 1980"], "facts_used": ["Founded 1980, family-owned and woman-owned, headquartered in Imperial, Missouri -> db and page ''/''", "Specializes in custom thermoformed plastic packaging with prototyping, assembly, JIT delivery, drop shipping -> page ''/''", "Offers patented VersaCLAM\u2122 technology and stock tooling program with 300+ cavities and 100+ clamshell sizes -> page ''/''", "Recycles 95% of scrap materials, facility uses LED lighting and solar panels -> page ''/''", "Serves retail and shipping industries -> page ''/''", "Female-owned recognized by St. Louis Business Journal Top Women Business Owner -> page ''/''"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Custom Plastic Packaging Manufacturer", "founded_year": "1980", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags